9	/**
10	 * Rejects creating an owner when the owner's city already contains 50 or more owners.
11	 * The count is taken over the existing owners (the new owner is not yet saved), matching
12	 * cities by exact value. At 50 or more existing owners in the city the request is a 409
13	 * Conflict (see {@link CityAtCapacityException}).
14	 */
15	public class EnsureCityCapacity {
16	
17	    private static final int CITY_CAPACITY = 50;
18	
19	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
20	            throws CityAtCapacityException {
21	        String city = request.getCity();
22	        long inCity = ownerRepository.findAll().stream()
23	            .filter(existing -> city != null && city.equals(existing.getCity()))
24	            .count();
25	        if (inCity >= CITY_CAPACITY) {
26	            throw new CityAtCapacityException(city, inCity);
27	        }
28	    }
29	}
