366	    /**
367	     * The owner's check digit: a single Luhn check digit (0-9) computed over the digits
368	     * contained in the {@code customerCode}, scanning right to left and doubling the
369	     * rightmost digit first; non-digit characters are ignored. Derived from the owner's
370	     * own fields; null when the customer code is absent.
371	     */
372	    @Transient
373	    public Integer getCheckDigit() {
374	        if (this.customerCode == null) {
375	            return null;
376	        }
377	        int sum = 0;
378	        boolean dbl = true;
379	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
380	            char c = this.customerCode.charAt(i);
381	            if (c < '0' || c > '9') {
382	                continue;
383	            }
384	            int d = c - '0';
385	            if (dbl) {
386	                d *= 2;
387	                if (d > 9) {
388	                    d -= 9;
389	                }
390	            }
391	            sum += d;
392	            dbl = !dbl;
393	        }
394	        return (10 - (sum % 10)) % 10;
395	    }
