397	    /**
398	     * The owner's membership points: a running score built from the owner's own fields.
399	     * Starts at 0 and gains 2 when an email address is present, a further 1 when the owner
400	     * has no namesakes ({@code namesakeCount} is 0), a further 2 when it belongs to a
401	     * household of 3 or more members ({@code householdSize} is 3 or more), and a further 3
402	     * for tenure of more than one elapsed fiscal year (the fiscal years, starting 1 July,
403	     * from {@link #registrationDate} to the current date). A newly created owner has zero
404	     * tenure, so the pre-tenure factors alone top out at 5 points. Derived from the owner's
405	     * own fields.
406	     */
407	    @Transient
408	    public Integer getMembershipPoints() {
409	        int points = 0;
410	        boolean hasEmail = this.email != null && !this.email.isBlank();
411	        if (hasEmail) {
412	            points += 2;
413	        }
414	        boolean unique = this.namesakeCount != null && this.namesakeCount == 0;
415	        if (unique) {
416	            points += 1;
417	        }
418	        boolean largeHousehold = this.householdSize != null && this.householdSize >= 3;
419	        if (largeHousehold) {
420	            points += 2;
421	        }
422	        boolean tenured = this.registrationDate != null
423	            && (fiscalYearOf(LocalDate.now()) - fiscalYearOf(this.registrationDate)) > 1;
424	        if (tenured) {
425	            points += 3;
426	        }
427	        return points;
428	    }
429	
430	    /**
431	     * The owner's membership level: a number from 1 to 4 derived by banding
432	     * {@link #getMembershipPoints()} — 1 for 0-1 points, 2 for 2-3, 3 for 4-5 and 4 for 6
433	     * or more. Derived from the owner's own fields, then capped by
434	     * {@link #membershipLevelCap} when set: a new owner's level cannot exceed one above the
435	     * current maximum level among their household members. With no existing household member
436	     * the cap is absent and the banded value stands.
437	     */
438	    @Transient
439	    public Integer getMembershipLevel() {
440	        int level = bandMembershipLevel(getMembershipPoints());
441	        if (this.membershipLevelCap != null && this.membershipLevelCap < level) {
442	            return this.membershipLevelCap;
443	        }
444	        return level;
445	    }
446	
447	    private static int bandMembershipLevel(int points) {
448	        if (points <= 1) {
449	            return 1;
450	        }
451	        if (points <= 3) {
452	            return 2;
453	        }
454	        if (points <= 5) {
455	            return 3;
456	        }
457	        return 4;
458	    }
