469	    /**
470	     * Region -> inclusive 4-digit postcode range {low, high}: NSW 2000-2099,
471	     * VIC 3000-3099, QLD 4000-4099. The single source of truth for the
472	     * postcode-to-region mapping, consulted by {@link #regionForPostcode(String)}
473	     * (used by locality derivation) and {@link #hasPostcodeRange(String)} (used by
474	     * postcode validation).
475	     */
476	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
477	        "NSW", new int[] {2000, 2099},
478	        "VIC", new int[] {3000, 3099},
479	        "QLD", new int[] {4000, 4099});
