481	    /**
482	     * Fixed region-to-timezone lookup table, mapping each region to its IANA timezone
483	     * name: NSW->Australia/Sydney, VIC->Australia/Melbourne, QLD->Australia/Brisbane.
484	     * Any region not listed (including {@code "UNKNOWN"}) has no timezone.
485	     */
486	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
487	        "NSW", "Australia/Sydney",
488	        "VIC", "Australia/Melbourne",
489	        "QLD", "Australia/Brisbane");
