491	    /**
492	     * The owner's locality: the REGION component of the owner's region-and-hash identity.
493	     * Read off the {@code customerCode} prefix (the part before the first {@code '-'}) when
494	     * a customer code is present, otherwise derived straight from the postcode via
495	     * {@link #identityRegion(String)}. Either way this yields the region the customer code
496	     * was built from — NSW/VIC/QLD, or {@code "UNKNOWN"} when the postcode is absent or in
497	     * no known range. Derived from the owner's own fields.
498	     */
499	    @Transient
500	    public String getLocality() {
501	        if (this.customerCode != null) {
502	            int dash = this.customerCode.indexOf('-');
503	            if (dash > 0) {
504	                return this.customerCode.substring(0, dash);
505	            }
506	        }
507	        return identityRegion(this.postcode);
508	    }
