510	    /**
511	     * The REGION component of an owner's region-and-hash identity: the region derived from
512	     * the postcode via {@link #regionForPostcode(String)} (NSW/VIC/QLD), or
513	     * {@code "UNKNOWN"} when the postcode is absent or in no known range. The single source
514	     * of truth for the identity's region, so the {@code customerCode} prefix and the
515	     * {@link #getLocality() locality} cannot drift apart.
516	     */
517	    public static String identityRegion(String postcode) {
518	        String region = regionForPostcode(postcode);
519	        return region != null ? region : "UNKNOWN";
520	    }
