522	    /**
523	     * The canonical region for a city per the fixed city-to-region table
524	     * ({@code Sydney->NSW}, {@code Melbourne->VIC}, {@code Brisbane->QLD}), or
525	     * {@code "UNKNOWN"} when the city is not in the table. The single source of truth
526	     * for the city-to-region mapping, used as the city's region in postcode validation.
527	     */
528	    public static String regionForCity(String city) {
529	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
530	    }
531	
532	    /**
533	     * The canonical region for a 4-digit postcode per the fixed range table
534	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099), or {@code null} when the postcode
535	     * is absent, not a well-formed integer, or in no known range. Reads the shared
536	     * {@link #REGION_POSTCODE_RANGES} table; used by {@link #identityRegion(String)}
537	     * for the identity's region and by postcode validation to range-check a submitted
538	     * postcode against its city's region.
539	     */
540	    public static String regionForPostcode(String postcode) {
541	        if (postcode == null) {
542	            return null;
543	        }
544	        int value;
545	        try {
546	            value = Integer.parseInt(postcode.trim());
547	        } catch (NumberFormatException ex) {
548	            return null;
549	        }
550	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
551	            int[] range = entry.getValue();
552	            if (value >= range[0] && value <= range[1]) {
553	                return entry.getKey();
554	            }
555	        }
556	        return null;
557	    }
