590	    /**
591	     * The owner's identity key: the lower-case hex SHA-256 of
592	     * {@code normalizedTelephone + "|" + lowerEmail + "|" + soundex(lastName)}. The
593	     * telephone is already stored in E.164 form, the email is lower-cased (an empty segment
594	     * when absent), and the last name is reduced to its {@link #soundex(String) Soundex}
595	     * code. This is the single identity used for duplicate detection: two owners with the
596	     * same key are the same person (a 409 on create); an owner whose key differs but whose
597	     * Soundex last name and postcode match an existing owner is a soft match instead.
598	     * Derived from the owner's own fields.
599	     */
600	    @Transient
601	    public String getIdentityKey() {
602	        String normalizedTelephone = keyPart(this.telephone);
603	        String lowerEmail = keyPart(this.email == null ? null : this.email.toLowerCase(Locale.ROOT));
604	        String soundexLastName = soundex(this.getLastName());
605	        return sha256Hex(normalizedTelephone + "|" + lowerEmail + "|" + soundexLastName);
606	    }
607	
608	    private static String keyPart(String value) {
609	        return (value == null || value.isBlank()) ? "" : value;
610	    }
611	
612	    /** Lower-case hex SHA-256 of the UTF-8 bytes of {@code value}. */
613	    private static String sha256Hex(String value) {
614	        try {
615	            byte[] digest = MessageDigest.getInstance("SHA-256")
616	                .digest(value.getBytes(StandardCharsets.UTF_8));
617	            StringBuilder sb = new StringBuilder(digest.length * 2);
618	            for (byte b : digest) {
619	                sb.append(String.format("%02x", b));
620	            }
621	            return sb.toString();
622	        }
623	        catch (NoSuchAlgorithmException ex) {
624	            throw new IllegalStateException("SHA-256 not available", ex);
625	        }
626	    }
