628	    /**
629	     * The American Soundex code of {@code name}: the upper-cased first letter followed by
630	     * three digits that encode the remaining consonants. Vowels and {@code H}/{@code W} are
631	     * not coded; adjacent letters with the same code collapse to one, as do two same-coded
632	     * letters separated only by {@code H} or {@code W}. The code is right-padded with zeros
633	     * and truncated to four characters. An absent or letter-free name yields the empty
634	     * string. The single source of truth for an owner's last-name phonetic key, used by the
635	     * {@link #getIdentityKey() identity key} and by soft-duplicate matching. It lives here
636	     * (rather than beside the exact-match name normalization in the package-private
637	     * {@code OwnerNames} helper) because {@code getIdentityKey()} is an entity-level derived
638	     * getter and must not depend on the request-function layer; the two are distinct name
639	     * concerns — exact comparison vs. phonetic keying — not a duplicated utility.
640	     */
641	    public static String soundex(String name) {
642	        if (name == null) {
643	            return "";
644	        }
645	        String letters = name.toUpperCase(Locale.ROOT).replaceAll("[^A-Z]", "");
646	        if (letters.isEmpty()) {
647	            return "";
648	        }
649	        StringBuilder code = new StringBuilder();
650	        code.append(letters.charAt(0));
651	        char prev = soundexDigit(letters.charAt(0));
652	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
653	            char c = letters.charAt(i);
654	            char digit = soundexDigit(c);
655	            if (digit != '0' && digit != prev) {
656	                code.append(digit);
657	            }
658	            // Vowels reset the previous code so same-coded consonants either side are coded
659	            // twice; H and W do not, so same-coded letters they separate still collapse.
660	            if (c != 'H' && c != 'W') {
661	                prev = digit;
662	            }
663	        }
664	        while (code.length() < 4) {
665	            code.append('0');
666	        }
667	        return code.toString();
668	    }
669	
670	    private static char soundexDigit(char c) {
671	        switch (c) {
672	            case 'B': case 'F': case 'P': case 'V':
673	                return '1';
674	            case 'C': case 'G': case 'J': case 'K': case 'Q': case 'S': case 'X': case 'Z':
675	                return '2';
676	            case 'D': case 'T':
677	                return '3';
678	            case 'L':
679	                return '4';
680	            case 'M': case 'N':
681	                return '5';
682	            case 'R':
683	                return '6';
684	            default:
685	                return '0';
686	        }
687	    }
