689	    /**
690	     * The stored E.164 {@link #telephone} formatted for humans: the country code,
691	     * a space, then the national digits grouped in threes (e.g.
692	     * {@code "+61 412 345 678"}). The {@code '+'} and country code are taken from the
693	     * E.164 value (a {@code '+1'} NANP country code is a single digit, any other is
694	     * treated as two digits, matching the recognized {@code '+61'}/{@code '+1'} forms),
695	     * and the national digits follow in space-separated groups of three. Returns the raw
696	     * value unchanged when it is absent or not a {@code '+'}-prefixed run of digits.
697	     * Derived from the owner's own fields; the raw {@link #telephone} stays E.164.
698	     */
699	    @Transient
700	    public String getTelephoneDisplay() {
701	        if (this.telephone == null || !this.telephone.startsWith("+")) {
702	            return this.telephone;
703	        }
704	        String digits = this.telephone.substring(1);
705	        if (!digits.matches("\\d+")) {
706	            return this.telephone;
707	        }
708	        int countryCodeLength = digits.startsWith("1") ? 1 : 2;
709	        if (digits.length() <= countryCodeLength) {
710	            return this.telephone;
711	        }
712	        String countryCode = digits.substring(0, countryCodeLength);
713	        String national = digits.substring(countryCodeLength);
714	        StringBuilder grouped = new StringBuilder();
715	        for (int i = 0; i < national.length(); i += 3) {
716	            if (grouped.length() > 0) {
717	                grouped.append(' ');
718	            }
719	            grouped.append(national, i, Math.min(i + 3, national.length()));
720	        }
721	        return "+" + countryCode + " " + grouped;
722	    }
723	
724	    protected Set<Pet> getPetsInternal() {
725	        if (this.pets == null) {
726	            this.pets = new HashSet<>();
727	        }
728	        return this.pets;
729	    }
730	
731	    protected void setPetsInternal(Set<Pet> pets) {
732	        this.pets = pets;
733	    }
734	
735	    public List<Pet> getPets() {
736	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
737	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
738	        return Collections.unmodifiableList(sortedPets);
739	    }
740	
741	    public void setPets(List<Pet> pets) {
742	        this.pets = new HashSet<>(pets);
743	    }
744	
745	    public void addPet(Pet pet) {
746	        getPetsInternal().add(pet);
747	        pet.setOwner(this);
748	    }
749	
750	    /**
751	     * Return the Pet with the given name, or null if none found for this Owner.
752	     *
753	     * @param name to test
754	     * @return true if pet name is already in use
755	     */
756	    public Pet getPet(String name) {
757	        return getPet(name, false);
758	    }
759	
760	    /**
761	     * Return the Pet with the given name, or null if none found for this Owner.
762	     *
763	     * @param name to test
764	     * @return true if pet name is already in use
765	     */
766	    public Pet getPet(String name, boolean ignoreNew) {
767	        name = name.toLowerCase();
768	        for (Pet pet : getPetsInternal()) {
769	            if (!ignoreNew || !pet.isNew()) {
770	                String compName = pet.getName();
771	                compName = compName.toLowerCase();
772	                if (compName.equals(name)) {
773	                    return pet;
774	                }
775	            }
776	        }
777	        return null;
778	    }
779	
780	    public Pet getPet(Integer petId) {
781	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
782	    }
783	
