785	    public String toString() {
786	        return new ToStringCreator(this)
787	
788	            .append("id", this.getId())
789	            .append("new", this.isNew())
790	            .append("lastName", this.getLastName())
791	            .append("firstName", this.getFirstName())
792	            .append("address", this.address)
793	            .append("city", this.city)
